SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");root:="work/deg10/continuation_20261030b/C81/";fp:=FrobeniusPolynomial(JH(81,[28]),2);if Type(fp) eq SeqEnum then fp:=&*fp;end if;order:=Integers()!Evaluate(fp,1);print "C81_Y46_FROBENIUS",order,Factorization(order),Cputime(tt);
Y:=MDX1(27,GF(2));C:=Curve(Y);F0,mp:=AlgorithmicFunctionField(FunctionField(C));F:=RationalExtensionRepresentation(F0);assert Genus(F) eq 13;E:=EllipticCurve([F!mp(v):v in Y`_E]);P:=E![0,0];assert 27*P eq E!0 and 9*P ne E!0;RX<X>:=PolynomialRing(F);S:=9*P;EG,phi:=IsogenyFromKernel(E,X-S[1]);dual:=DualIsogeny(phi);dp:=DefiningPolynomials(dual);
nx:=Evaluate(dp[1],[X,RX!0,RX!1]);dx:=Evaluate(dp[3],[X,RX!0,RX!1]);cc:=GCD(nx,dx);nx div:=cc;dx div:=cc;assert Degree(nx) eq 3 and GCD(nx,dx) eq 1;nx/:=LeadingCoefficient(nx);assert IsIrreducible(nx);L<z>:=FunctionField(nx);RY<V>:=PolynomialRing(L);aa:=aInvariants(EG);rel:=V^2+((L!aa[1])*z+L!aa[3])*V-(z^3+(L!aa[2])*z^2+(L!aa[4])*z+L!aa[5]);yn:=Evaluate(dp[2],[RY!z,V,RY!1]) mod rel;assert Degree(yn) eq 1;yz:=-Coefficient(yn,0)/Coefficient(yn,1);ELL:=EllipticCurve([L!v:v in aa]);Q:=ELL![z,yz];assert 27*Q eq ELL!0 and 9*Q ne ELL!0;im:=[Evaluate(v,[z,yz,L!1]):v in dp];assert im[3] ne 0 and im[1]/im[3] eq 0 and im[2]/im[3] eq 0;
LF:=RationalExtensionRepresentation(L);assert Genus(LF) eq 46;coords:=[LF!(L!(F!mp(v))):v in Y`_coordinates_xy] cat [LF!z];
function ER(v) return [[Integers()!a:a in Coefficients(Numerator(v))],[Integers()!a:a in Coefficients(Denominator(v))]];end function;
function EF(v) return [ER(c):c in Eltseq(LF!v)];end function;
Write(root cat "y46_model.m",Sprint([*[ER(c):c in Coefficients(DefiningPolynomial(LF))],[EF(v):v in coords],order,[EF(LF!(L!v)):v in aInvariants(E)],[EF(LF!(L!v)):v in aa],EF(LF!yz)*]):Overwrite:=true);print "C81_Y46_MODEL_COMPLETE",Genus(LF),Degree(LF),order,Cputime(tt);quit;
